def Reduced_String(k, s):
    stack = []
    count_stack = []

    for char in s:
        if stack and stack[-1] == char:
            stack.append(char)
            count_stack[-1] += 1
            if count_stack[-1] == k:
                stack.pop()
                count_stack.pop()
        else:
            stack.append(char)
            count_stack.append(1)

    return ''.join(stack)

# Example usage:
# k = 2
# s = "geeksforgeeks"
